from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, computed in
    parallel with a thread pool. The result is in input order and does
    not depend on the number of workers. Negative numbers have parity
    1 if odd (e.g. -3 -> 1)."""
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-1, -2, -3, 0]) == [1, 0, 1, 0]


def test_parities_large_ints() -> None:
    assert parities([2**100, 2**100 + 1]) == [0, 1]


def test_parities_order_preserved() -> None:
    xs = list(range(1000))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_repeated_calls_deterministic() -> None:
    xs = [7, 8, 9, 10, 11] * 50
    expected = [x % 2 for x in xs]
    for _ in range(5):
        assert parities(xs) == expected


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 6, 7]
    parities(xs)
    assert xs == [5, 6, 7]


def test_parities_values_are_ints_zero_or_one() -> None:
    result = parities(list(range(-50, 50)))
    assert all(r in (0, 1) for r in result)
    assert len(result) == 100

